// DM mission files: Street Commissions, part 2 (Glasshouse, Backroom, Night Market, Mutual, Lantern Desk, Meridian, Red Thread, citywide).
// The paint roll itself is always Graft, rolled from Tag Studio (Alt+G); the checks here are the ones the GM calls around it.
// Quality tiers: Proper Mess, Bad Luck, Just About, Sorted, Smashed It, Legendary.
export default {
  'tg-ge-01': {
    brief: `The Glasshouse Exchange sponsors two sanctioned art plates connected to a sale: the Glasshouse Saleroom service shutter and the Estorick pop-up board. The art comparison should show actual vector layers in Tag Studio, not just prose. The twist: a signature has been copied. Use the correct variant to identify the fake.`,
    openTitle: `Read aloud: Wren signs his work`,
    open: `Clement Wren holds up two cards, each with a small painted glyph: a prism with a line through it. They look identical. "One of these is my mark," he says. "The other is a forgery that has been appearing on certain lots." He smiles. "Paint mine on my shutter and on the Estorick board. Correctly." He hands you the real one. "Then we'll see who's been copying my hand."`,
    cast: ['clement-wren', 'iris-bellamy'],
    roles: {'clement-wren': `Wants his mark painted correctly, to expose a forger.`, 'iris-bellamy': `At the Estorick. Can spot the difference between the two marks.`},
    scenes: [
      {at: 'SP-CG-GLASSHOUSE', title: `The Glasshouse Saleroom service shutter`, read: `The courier yard behind the Glasshouse Saleroom. The service shutter is pale grey, sanctioned, and lit by a single lamp. Clement watches from his office window with a glass of brandy.`,
        text: `Sanctioned. Compare the two marks in Tag Studio's layers before painting.`,
        checks: [['sav', 'medium', `Spot the difference between Clement's mark and the forgery`, `The real prism's line goes top-left to bottom-right. The fake goes the other way.`, `They look the same to you.`]]},
      {at: 'SP-CG-ESTORICK', title: `The Estorick pop-up board`, read: `A pop-up board outside the Estorick Collection on Canonbury Square, for an exhibition. Iris Bellamy, in white gloves, comes out to watch. She holds up a catalogue: a lot with the forged prism on it. "That one," she says. "Look at the line."`,
        text: `Sanctioned. Paint the correct variant beside the catalogue's forged one.`,
        checks: [['grt', 'easy', `Get the fine detail right with a small nozzle, slowly`, `Crisp. Sorted.`, `Smudged. Just About.`],
          ['grf', 'medium', `Lift the catalogue page with the forged mark for Clement, without Iris's colleague noticing`, `In your pocket.`, `The colleague notices.`]]}
    ],
    closeTitle: `Read aloud: who's been copying`,
    close: `Clement holds the catalogue page beside your photo of the real mark. The lines go opposite ways. "Ah," he says softly. "Left-handed." He sets down his brandy. "There's only one left-handed restorer who knows my work that well." He doesn't say the name. He doesn't need to: Luca Ferretti has painted for him for twenty years. "Well," Clement says. "That will be an awkward lunch."`,
    notes: [`Sanctioned art plates. The vector layers in Tag Studio show the difference.`,
      `The forger is left-handed: a hook for GE and the restorer Luca Ferretti.`,
      `Reward: £65. Leads to TG-GE-02.`]
  },
  'tg-ge-02': {
    brief: `A trio of glass shards hides a provenance trail, each in a different district: the Orchard Lease Office shutter, the Split Second Archive street shutter and the Queensbridge Sound Store hire shutter. Sorted or better. Non-criminal proof photos are allowed where permission applies. The twist: the original seller used the same style to launder the history.`,
    openTitle: `Read aloud: the missing shard`,
    open: `Clement lays three pieces of a broken glass panel on his desk. Each has a different symbol etched into it. "A provenance trail," he says. "Three shards, three places. Whoever owned this panel marked each place it was kept." He slides a photo across. "Paint each shard where it belongs. Then we'll see where the panel really came from."`,
    cast: ['clement-wren', 'ada-march', 'mina-dey'],
    roles: {'clement-wren': `Following a provenance trail.`, 'ada-march': `"Index." Lets you paint the Archive shutter. Has a card for every shard.`, 'mina-dey': `At the Orchard Lease Office. Nervous about anything on her shutter.`},
    scenes: [
      {at: 'SP-HB-ORCHARD', title: `The Orchard Lease Office shutter`, read: `The Orchard Lease Office on Highbury Grove, after hours. Mina Dey is locking up. "Not on the shutter," she says, panicking. "Please. My boss." She looks round. "Okay. Small. Quick."`,
        text: `Permission, just about.`,
        checks: [['frt', 'easy', `Reassure Mina it'll be small and tasteful`, `"Small. Okay."`, `She rings her boss.`]]},
      {at: 'SP-DB-ARCHIVE', title: `The Split Second Archive street shutter`, read: `The street shutter at the Split Second Archive. Index unlocks the front door and stands on the step with an index card. "Shard two," she says. "I've got a card for it. 1962. A shop on Morning Lane." She looks at you. "Same style as the Meridian brochures."`,
        text: `The twist: the seller used the same style to launder the history.`,
        checks: [['mov', 'easy', `Climb the railing to reach the top of the shutter`, `Up and steady.`, `Wobbly.`]]},
      {at: 'SP-HR-QUEENSBRIDGE', title: `The Queensbridge Sound Store hire shutter`, read: `The Queensbridge Sound Store's hire shutter, again. Your intro tag is still there. Amina's light is off for once.`,
        text: `Unpermitted this time. Heat if witnessed.`,
        checks: [['sav', 'medium', `Check the street for anyone watching before you start`, `Clear.`, `A man walking a dog stops to watch.`],
          ['whl', 'medium', `Get back to Clement's with all three photos before the sale opens`, `On his desk as the doors open.`, `The sale's started.`]]}
    ],
    closeTitle: `Read aloud: laundered`,
    close: `Clement lays your three photos beside the three shards. Highbury, De Beauvoir, Haggerston. "Morning Lane, 1962," he says. "Then a lettings office. Then a sound store." He sits back. "Someone painted a fake history in the same style as the real one, to make the panel look older and more valuable." He sighs. "Provenance, my dears. Just a story somebody paid to have told well."`,
    notes: [`Sorted or better.`,
      `Non-criminal proof photos are allowed where permission applies.`,
      `Reward: £130 and 1 GE Renown. Leads to TG-GE-03.`]
  },
  'tg-ge-03': {
    brief: `An ambitious exhibition wants a visible three-part prism run: the Stratford loading-bay wall, the VeloPark approach footbridge panel and the Bow Flyover column. A meaningful choice to accept, reject or take a permitted alternative. One Smashed It or better. The twist: a patron offers more money to deface a rival mark.`,
    openTitle: `Read aloud: the prism line`,
    open: `Clement unrolls a design: three prisms, each splitting light into a rainbow, connected by a line across a map. "The Prism Line," he says. "An exhibition across three sites. Stratford, the VeloPark, the flyover." He taps the flyover. "There's a rival mark there. A patron of mine would pay double if you painted over it." He looks at you. "I'm merely passing on the offer."`,
    cast: ['clement-wren', 'evie-slate'],
    roles: {'clement-wren': `Passes on the offer, neutrally.`, 'evie-slate': `The patron offering more money to deface a rival mark.`},
    scenes: [
      {at: 'SP-ST-WESTFIELD', title: `The Stratford loading-bay wall`, read: `The loading bay at Westfield. Permitted, through the exhibition. A huge wall, perfect for the first prism.`,
        text: `Go for Smashed It here.`,
        checks: [['grt', 'medium', `Spend two hours on the rainbow gradient`, `Smashed It.`, `Sorted.`]]},
      {at: 'SP-ON-VELO', title: `The VeloPark approach footbridge panel`, read: `The footbridge panel on the way to the VeloPark. Cyclists stream past. A woman in a black polo neck with three phones leans on the railing. "Evie Slate," she says. "The patron." She points across the park at the flyover. "There's a Lea Boys reed on that column. Paint over it, and I'll double your fee."`,
        text: `The twist: the patron offers more money to deface a rival mark.`,
        checks: [['btl', 'medium', `Tell Evie no, to her face`, `She shrugs. "Your loss."`, `You hesitate. She smiles.`],
          ['mus', 'easy', `Help a cyclist whose chain's come off while you wait for the bridge to clear`, `He thanks you, and moves on. Clear bridge.`, `You get oil everywhere.`]]},
      {at: 'SP-BF-PILLAR', title: `The Bow Flyover column`, read: `The Bow Flyover column. A Lea Boys reed is painted on one side. A clean space is on the other. A permitted alternative hoarding is round the corner.`,
        text: `Accept, reject, or take the permitted alternative.`,
        checks: [['mov', 'medium', `Cross to the column between lorries`, `Across in one gap.`, `A horn blares.`],
          ['grf', 'medium', `Unlock the hoarding's padlock if you choose the permitted alternative (the key's been lost)`, `Click. Open.`, `It won't open.`]]}
    ],
    closeTitle: `Read aloud: light split three ways`,
    close: `At the exhibition opening, Clement stands with a glass of champagne in front of a photo of the three prisms: Stratford, the VeloPark, the flyover. "The Prism Line," he says to the crowd. "Light, split three ways." He catches your eye. If you painted over the reed, he raises his glass slightly. If you didn't, he raises it a little higher.`,
    notes: [`A meaningful choice to accept, reject or take a permitted alternative.`,
      `Overpainting the Lea Boys reed affects LB stance.`,
      `Reward: £220. Completes the GE tagging line.`]
  },
  'tg-bb-01': {
    brief: `Vic wants two coded signs to tell runners which book is open: the Third Half Bookroom shutter and the Shepherdess Coin Rooms back-lane shutter. This unlocks the Backroom Odds pack. No gambling mechanics needed. The twist: one sign uses yesterday's odds and causes a street dispute.`,
    openTitle: `Read aloud: odds on the wall`,
    open: `Vic draws two symbols on a betting slip with a fountain pen: a horseshoe, open end up, and a horseshoe, open end down. "Up means the book's open," he says. "Down means it's shut. Runners see it from across the road and know whether to come in." He folds the slip. "Two shutters. The Third Half and the Coin Rooms." He tucks the slip into your pocket. "And get today's right, son. Not yesterday's."`,
    cast: ['victor-randle', 'eddie-lane'],
    roles: {'victor-randle': `Vic. Wants coded signs for his runners.`, 'eddie-lane': `Cashier. Knows which book is open today.`},
    scenes: [
      {at: 'SP-LY-THIRDHALF', title: `The Third Half Bookroom shutter`, read: `The shutter of the Third Half Bookroom on High Road Leyton, down for the night. Eddie Lane is locking up. "Book's open tomorrow," he says. "Horseshoe up."`,
        text: `Sanctioned by Vic.`,
        checks: [['sav', 'easy', `Check with Eddie which way the horseshoe should go today`, `Up. Open.`, `You forget to ask.`]]},
      {at: 'SP-HX-CASHROOM', title: `The Shepherdess Coin Rooms back-lane shutter`, read: `The rear passage behind the Shepherdess Coin Rooms. There's already a horseshoe on the shutter: open end down. Yesterday's sign. Two runners are standing in front of it, arguing. "It says shut!" "Eddie said it's open!"`,
        text: `The twist: yesterday's sign causes a street dispute.`,
        checks: [['frt', 'medium', `Settle the runners' argument before it turns into a fight`, `"It's open today. Yesterday's sign." They calm down.`, `One shoves the other.`],
          ['mus', 'easy', `Pull the two runners apart when it kicks off`, `Separated.`, `You get an elbow in the face.`]]}
    ],
    closeTitle: `Read aloud: horseshoes`,
    close: `Vic stands in the rear passage behind the Coin Rooms, looking at the horseshoe, open end up. "Up," he says. "Lovely." He takes out his betting slip and tears it in two. "Yesterday's odds," he says. "Never trust them." He looks at you. "That's the first thing my dad taught me." He tucks the halves into his breast pocket. "The second thing was: never lend money. Lend time."`,
    notes: [`Unlocks the Backroom Odds tag pack. No gambling mechanics.`,
      `Yesterday's sign causes a dispute: a light roleplay moment.`,
      `Reward: £65. Leads to TG-BB-02.`]
  },
  'tg-bb-02': {
    brief: `A route from matchday supporters to a venue mural, with each placement logged: the Leyton Orient supporter shuttle bus (parked), the Marshes pavilion boundary wall and the De Beauvoir Block authorised mural. Sorted or better. The quality bonus applies once per unique spot. The twist: the second site contains a counterfeit marker.`,
    openTitle: `Read aloud: across the book`,
    open: `Vic spreads a matchday programme on his desk. "Orient at home, Saturday," he says. "Supporters' bus parks on Brisbane Road. Then they go to the Marshes for the kids' match, then De Beauvoir for the do." He circles each. "Horseshoe on each. So my runners can follow the punters." He smiles. "Business follows people, son."`,
    cast: ['victor-randle', 'pauline-moss', 'ollie-grant'],
    roles: {'victor-randle': `Wants his runners to follow the punters.`, 'pauline-moss': `Supporters' organiser. Won't have anything nasty on her bus.`, 'ollie-grant': `Groundsman. Found a fake horseshoe on his wall.`},
    scenes: [
      {at: 'SP-LY-ORIENT-BUS', title: `The Leyton Orient supporter shuttle bus`, read: `The supporters' shuttle bus, parked on Brisbane Road before the match. Pauline Moss, in her Orient scarf, stands guarding the door with a collection bucket. "Nothing rude," she says. "It's a family bus."`,
        text: `The bus must be parked.`,
        checks: [['frt', 'easy', `Persuade Pauline a small horseshoe is "lucky"`, `"Oh, go on then. For luck."`, `"No."`]]},
      {at: 'SP-HM-NORTH-PAVILION', title: `The Marshes pavilion boundary wall`, read: `The North Pavilion wall on the Marshes. Ollie Grant points his strimmer at it. "Somebody's already painted one," he says. A horseshoe: but the shoe has seven nail holes instead of eight. "Counterfeit," Ollie says. "Vic's has eight."`,
        text: `The twist: a counterfeit marker. Paint the real one beside or over it.`,
        checks: [['sav', 'medium', `Spot the counterfeit's tell`, `Seven nail holes. Vic's has eight.`, `It looks real.`],
          ['grt', 'easy', `Help Ollie re-mark the touchline you trampled getting here`, `He forgives you.`, `He doesn't.`]]},
      {at: 'SP-DB-DEBEAUVOIR', title: `The De Beauvoir Block authorised mural`, read: `The authorised mural wall at the De Beauvoir Block. A party's happening inside: Orient fans celebrating. Somebody's playing Chas & Dave.`,
        text: `Authorised. Sorted or better.`,
        checks: [['mov', 'medium', `Get up the scaffold to the clean top section`, `Up. Perfect spot.`, `You knock a paint tin off.`],
          ['whl', 'medium', `Get from the Marshes to De Beauvoir before the party ends`, `Painting as the last song plays.`, `Everyone's gone home.`]]}
    ],
    closeTitle: `Read aloud: eight nails`,
    close: `Vic counts the nail holes on the photo of the pavilion wall: seven on the fake, eight on yours. "Seven," he says. "Someone's copying my book." He puts the photo down. "First the duplicate ledger, now this." He drums his fingers. "Someone in this borough wants my punters." He looks at you. "Find out who, son. There's a drink in it."`,
    notes: [`The bus must be parked. The quality bonus applies once per unique spot.`,
      `The counterfeit horseshoe links to the duplicate book in BB1.`,
      `Reward: £130 and 1 BB Renown. Leads to TG-BB-03.`]
  },
  'tg-bb-03': {
    brief: `Vic sends the crew into hostile corridors for a coded advertising war: the Lea Bridge Social Rooms side wall, the East Cross overpass pillar and the Hackney Empire loading shutter. One Smashed It or better. Street outcomes affect faction stance but can't farm infinite Renown. The twist: the final mark threatens a public event; a non-criminal alternative is available.`,
    openTitle: `Read aloud: the bookies' countermark`,
    open: `Vic is not smiling. "Someone's painting fake horseshoes all over my patch," he says. "So we go into theirs." He draws three crosses on a map: Clapton, the A12, Mare Street. "Lea Boys wall. Rusk's overpass. The Empire." He looks at you. "Horseshoes. Big ones. Let them know whose book is open." He pauses. "Carefully, son. Carefully."`,
    cast: ['victor-randle', 'tessa-price'],
    people: {'martin-rusk': {}},
    roles: {'victor-randle': `Starting an advertising war.`, 'tessa-price': `Moth. Watches the Social Rooms wall.`, 'martin-rusk': `His people patrol the East Cross overpass.`},
    scenes: [
      {at: 'SP-CL-LEABRIDGE', title: `The Lea Bridge Social Rooms side wall`, read: `The Social Rooms wall, again. Moth's reed, your old marks, and a space. Moth is not on her bench tonight.`,
        text: `Hostile corridor. Heat applies.`,
        checks: [['btl', 'medium', `Paint in Lea Boys territory with three of Stretch's lot watching from the car park`, `They watch. They don't move.`, `They start walking over.`]]},
      {at: 'SP-WW-EASTCROSS', title: `The East Cross overpass pillar`, read: `The East Cross overpass on the A12. A black van with no markings is parked under it. Two men in black fleeces sit inside.`,
        text: `Rusk's people. High risk.`,
        checks: [['mov', 'medium', `Get to the far side of the pillar without the van seeing`, `Unseen.`, `The van's headlights come on.`],
          ['grf', 'medium', `Open the overpass maintenance hatch to paint from inside the structure, out of sight`, `Click. In.`, `Rusted shut.`]]},
      {at: 'SP-HC-EMPIRE-BAY', title: `The Hackney Empire loading shutter`, read: `The loading court behind the Hackney Empire. A children's matinee is about to start: parents, buggies, excited kids streaming in. The loading shutter is right next to the queue.`,
        text: `The twist: the final mark threatens a public event. A non-criminal alternative (a sanctioned board) is available.`,
        checks: [['frt', 'medium', `Ask the theatre manager for the sanctioned board instead`, `"Fine. Not on the shutter during a kids' show." Board's yours.`, `"No."`],
          ['grt', 'medium', `Wait three hours for the matinee to end before painting`, `Empty court. Smashed It.`, `You give up and paint in a rush.`]]}
    ],
    closeTitle: `Read aloud: whose book is open`,
    close: `Vic studies the three photos in his private parlour: Clapton, the A12, the Empire. "Lea Boys, Rusk and a theatre full of kiddies," he says. "You've had a busy night." He pours you a Scotch. "Nobody's going to forget whose book is open." He sips. "And the Empire?" You tell him what you did about the matinee. He nods slowly. "Good lad," he says. "Never upset the kiddies. They grow up to be punters."`,
    notes: [`One Smashed It or better.`,
      `Street outcomes affect faction stance but can't farm infinite Renown.`,
      `The matinee choice is a moral beat. Reward the non-criminal alternative.`,
      `Reward: £220. Completes the BB tagging line.`]
  },
  'tg-nm-01': {
    brief: `Pearl marks an unloading pattern across two market fronts: the Roman Exchange stall shutter and the New Spitalfields unloading shutter. An approved market sign mode is available if the stallholder agrees. The twist: a stallholder sees a different signal on an unlisted shutter.`,
    openTitle: `Read aloud: follow the lantern`,
    open: `Pearl draws a lantern on a paper bag with a market crayon: a box with a handle, and four little lines for light. "The lantern," she says. "Where you see it, a trader can unload and nobody'll touch their stock." She hands you the bag. "Two shutters. Mine, and the one at Spitalfields." She smiles. "Everybody eats, love."`,
    cast: ['pearl-okonkwo', 'marisol-vega'],
    roles: {'pearl-okonkwo': `Marking safe unloading points for her traders.`, 'marisol-vega': `Night forewoman at New Spitalfields. Lets you use the unloading shutter.`},
    scenes: [
      {at: 'SP-OF-ROMAN', title: `The Roman Exchange stall shutter`, read: `Roman Road at dawn, market traders setting up. Pearl's stall shutter at Roman Exchange. A trader at the next stall, an old man with a cart of fruit, frowns at your can. "There's another lantern on Mrs Ade's shutter round the corner," he says. "Not Pearl's. Different."`,
        text: `Approved market sign. The twist: a stallholder sees a different signal on an unlisted shutter.`,
        checks: [['sav', 'medium', `Go round the corner and compare the other lantern`, `Three lines of light instead of four. A fake. Len Fisk's?`, `It looks the same.`]]},
      {at: 'SP-HM-MARKET', title: `The New Spitalfields unloading shutter`, read: `New Spitalfields at 4am, lorries backing into bays. Marisol Vega points at an unloading shutter. "That one," she says. "Paint it before the next lorry. I can count, love. You've got four minutes."`,
        text: `Four minutes before the next lorry.`,
        checks: [['mov', 'medium', `Paint between reversing lorries without getting run over`, `Done and clear.`, `A lorry beeps at you. Twice.`],
          ['mus', 'easy', `Shift a pallet blocking the shutter`, `Moved.`, `It won't budge. Paint round it.`]]}
    ],
    closeTitle: `Read aloud: four lines`,
    close: `Pearl looks at the photo of the fake lantern on Mrs Ade's shutter: three lines of light. Then at yours: four. "Three," she says. "Somebody's copying my lantern with three lines." She folds the paper bag. "Len Fisk can't count," she says. "Never could." She laughs, the big booming laugh. "Paint over it, love. With four."`,
    notes: [`An approved market sign mode is available if the stallholder agrees.`,
      `The fake lantern hints at Len Fisk (NM career).`,
      `Reward: £65. Leads to TG-NM-02.`]
  },
  'tg-nm-02': {
    brief: `Three lantern marks help separate legitimate couriers from decoys: the Bethnal Green market service shutter, the Larch Cold Store outer wall and the Queensbridge Sound Store hire shutter. Sorted or better. The twist: one false paint job points towards Dead Air's missing recordings.`,
    openTitle: `Read aloud: two buyers, no map`,
    open: `Pearl rings from her stall. "Couriers are turning up at the wrong places, love. Two buyers, no map." She sighs. "I want lanterns at three drops. Bethnal Green, the Larch, Queensbridge. So the real couriers know where to go and the decoys don't." A pause. "And someone's painted a lantern on the Queensbridge shutter already. Not mine. Find out why."`,
    cast: ['pearl-okonkwo', 'amina-keane'],
    people: {'dee-hassan': {}},
    roles: {'pearl-okonkwo': `Separating real couriers from decoys.`, 'amina-keane': `Owns the Queensbridge shutter. Saw who painted the fake.`, 'dee-hassan': `Recognises what the fake lantern is pointing to.`},
    scenes: [
      {at: 'SP-BG-STREET', title: `The Bethnal Green market service shutter`, read: `The service shutter at Bethnal Green market, behind the stalls. Traders packing up. A fruit seller hands you a banana. "For energy," she says.`,
        text: `Sorted or better.`,
        checks: [['grt', 'easy', `Paint in the drizzle after a long day`, `Sorted.`, `Just About.`]]},
      {at: 'SP-LY-LARCH', title: `The Larch Cold Store outer wall`, read: `The Larch Cold Store wall again: the Lea Boys reed, the old lantern. Space for one more.`,
        text: `Contested, but shared (from TG-LB-01).`,
        checks: [['mov', 'easy', `Climb onto the loading dock to reach the clean space`, `Up.`, `You slip.`]]},
      {at: 'SP-HR-QUEENSBRIDGE', title: `The Queensbridge Sound Store hire shutter`, read: `The Queensbridge shutter, crowded now with tags. One of them is a lantern with an arrow pointing down. Amina Keane comes down in her dressing gown. "A man painted that last week," she says. "Sunglasses. At night." She points at the arrow. "Pointing at my cellar."`,
        text: `The twist: the false lantern points towards Dead Air's missing recordings.`,
        checks: [['grf', 'medium', `Get into Amina's cellar (with her permission) and see what the arrow points to`, `A box of old tapes, labelled DEAD AIR 2016. The missing reel from RT1.`, `The cellar door's stuck.`],
          ['frt', 'easy', `Persuade Amina to let you look in her cellar`, `"Go on, then. Mind the mice."`, `"It's two in the morning."`]]}
    ],
    closeTitle: `Read aloud: sunglasses at night`,
    close: `Dee Hassan holds a reel of tape from Amina's cellar up to the light. "DA-2016-114," she reads. "The missing reel." She looks at the lantern on the shutter, with its arrow pointing down. "A man in sunglasses hid this here and marked it with Pearl's lantern," she says. "So whoever was meant to collect it would think it was market stock." She puts the reel in her bag. "Bram Senn."`,
    notes: [`Sorted or better.`,
      `The false lantern hides Dead Air's missing reel (RT1). Bram Senn hid it.`,
      `Reward: £130 and 1 NM Renown. Leads to TG-NM-03.`]
  },
  'tg-nm-03': {
    brief: `Leave a citywide sign on rail, bus and depot before the Banana Watch window closes: the Temple Mills depot carriage, the Waterden Road parked bus and the Marshgate Delivery Depot outer wall. A specific Watch deadline, not real time; assets are stationary. One Smashed It or better. The twist: Pearl's buyer is late; the player chooses whether to let the mark expire.`,
    openTitle: `Read aloud: market after midnight`,
    open: `Pearl checks her Banana Watch. "Midnight market," she says. "Three lanterns before two o'clock. Rail, bus, depot. So the night traders know where to set up." She taps the watch. "Two o'clock, love. Not five past." She looks out at the dark. "And my buyer's late. If he doesn't show, the marks don't matter."`,
    cast: ['pearl-okonkwo', 'gita-mercer'],
    roles: {'pearl-okonkwo': `Running a midnight market.`, 'gita-mercer': `At Marshgate. Will let you paint the depot wall before her shift ends.`},
    scenes: [
      {at: 'SP-HM-TEMPLE-TRAIN', title: `The Temple Mills depot carriage`, read: `Temple Mills, the carriage at the end of the siding. Your old marks from other jobs are on it. Space for a lantern.`,
        text: `Trains add three minutes on the Watch.`,
        checks: [['sav', 'easy', `Spot the depot patrol's torch before they spot you`, `Eight minutes clear.`, `The torch is on you.`]]},
      {at: 'SP-VW-WATERDEN-BUS', title: `The Waterden Road parked bus`, read: `The Waterden Road bus, parked up. Your tags, Owen's Velvet Circuit, a Dead Air wave. Room for a lantern.`,
        text: `Go for Smashed It here.`,
        checks: [['grt', 'medium', `Take the time to do it properly, even with the clock ticking`, `Smashed It.`, `Rushed. Sorted.`]]},
      {at: 'SP-BF-MARSHGATE', title: `The Marshgate Delivery Depot outer wall`, read: `The Marshgate depot wall, at 1.50am. Gita Mercer stands at the gate with her clipboard. "Shift ends at two," she says. "After that, it's security." Pearl rings: "Buyer's still not here. Do I wait?"`,
        text: `The twist: Pearl's buyer is late. The crew choose whether to let the mark expire.`,
        checks: [['whl', 'medium', `Race from Waterden Road to Marshgate before two`, `1.52. Eight minutes.`, `2.04. Security.`],
          ['btl', 'medium', `Tell Pearl honestly what you think she should do about the late buyer`, `She listens. "You're right." She decides.`, `You fudge it. She decides alone.`]]}
    ],
    closeTitle: `Read aloud: after midnight`,
    close: `At 2.15am, under the lantern at Marshgate, the midnight market springs up out of nowhere: vans open, tables out, torches, music, traders selling everything from mangoes to bike parts. Pearl walks among them in her apron, cash bag on her belt, laughing her big laugh. Whether her buyer turned up or not, the market's here. "Everybody eats," she says. "Even at two in the morning."`,
    notes: [`A specific Banana Watch deadline, not real time. Assets are stationary.`,
      `One Smashed It or better.`,
      `The late buyer is a choice: let the mark expire, or wait.`,
      `Reward: £220. Completes the NM tagging line.`]
  },
  'tg-bm-01': {
    brief: `Rosa organises two permission-based community murals with useful contact details: the Hub67 community panel and the Approach Recovery Rooms awareness board. Legal murals; police Heat is never generated solely for visible artwork. The twist: a fake organiser wants the slogan used as cover for a scam.`,
    openTitle: `Read aloud: mutual aid mural`,
    open: `Rosa lays two designs on the kitchen table at Saint Martha House: a pair of hands holding a house, and the words "BOROUGH MUTUAL — YOU'RE NOT ON YOUR OWN — " followed by a phone number. "Two murals," she says. "Hub67 and the Recovery Rooms. People who need help should see where to get it." She taps the number. "Get the number right, love. Every digit."`,
    cast: ['rosa-baptiste', 'tariq-evans', 'vee-calder'],
    roles: {'rosa-baptiste': `Wants useful murals with the right number.`, 'tariq-evans': `At the Recovery Rooms. Approves the board.`, 'vee-calder': `At Hub67. Films the mural going up.`},
    scenes: [
      {at: 'SP-WW-HUB67', title: `The Hub67 community panel`, read: `The community panel outside Hub67 on Rothbury Road. Vee Calder sets up her camera. "Time-lapse," she says. "For the website." A man in a smart jacket wanders over. "Lovely mural," he says. "Could you change the number? I'm from the Mutual too. New number."`,
        text: `The twist: a fake organiser wants the slogan used to cover a scam.`,
        checks: [['sav', 'medium', `Check the man's "new number" against Rosa's`, `It's a premium-rate line. A scam.`, `It sounds plausible.`],
          ['frt', 'medium', `Send the fake organiser packing in front of Vee's camera`, `He leaves fast. Vee has him on film.`, `He argues. It's awkward.`]]},
      {at: 'SP-BG-RECOVERY', title: `The Approach Recovery Rooms awareness board`, read: `The awareness board outside the Approach Recovery Rooms. Tariq Evans comes out to watch, NHS lanyard on. "It matters," he says. "People walk past here on the worst day of their life. They should see a number."`,
        text: `Legal. No Heat for the artwork.`,
        checks: [['grt', 'easy', `Paint every digit of the phone number twice, carefully`, `Every digit perfect.`, `One digit's smudged. Fix it.`],
          ['mus', 'easy', `Carry the heavy primer tins from the van`, `Done.`, `You drop one.`]]}
    ],
    closeTitle: `Read aloud: not on your own`,
    close: `A week later, Rosa rings. "Fourteen calls," she says. "Fourteen people who saw the murals and rang the number." Her voice cracks slightly. "One of them was sleeping in a car." She clears her throat. "And Vee's film of that man with the fake number has been seen two thousand times. The police want to talk to him." She laughs. "Not on your own, love. Never on your own."`,
    notes: [`Legal murals: never generate police Heat solely for visible artwork.`,
      `The fake organiser is a scammer. Vee's film catches him.`,
      `Reward: £65. Leads to TG-BM-02.`]
  },
  'tg-bm-02': {
    brief: `Three approved public boards guide residents to welfare resources: the St John outreach board, the Clapton Library outreach panel and the Abney exterior community panel. Sorted or better. Board cleanup and repaint shows the contested-site lifecycle. The twist: someone defaces one board, and the crew must restore it.`,
    openTitle: `Read aloud: a different kind of notice`,
    open: `Rosa holds up a council notice: "NOTICE OF VACANCY". Then she holds up her own design: "NOTICE: YOU HAVE RIGHTS. Free advice, Tuesdays, Saint Martha House." She puts them side by side. "They put up notices," she says. "So do we." She hands you a list. "Three boards. Approved. Make them proper."`,
    cast: ['rosa-baptiste', 'lenora-pike', 'nadia-sayeed'],
    roles: {'rosa-baptiste': `Putting up rights notices.`, 'lenora-pike': `Tenants' secretary at St John. Has forty-one letters, and is writing the forty-second.`, 'nadia-sayeed': `Kiosk owner by Clapton Library. Saw who defaced the board.`},
    scenes: [
      {at: 'SP-WS-STJOHN', title: `The St John outreach board`, read: `The outreach board outside St John of Jerusalem on Lauriston Road. Lenora Pike, in a rain hat, holds a plastic folder of letters. "Forty-one letters to the council," she says. "This board will do more than all of them."`,
        text: `Approved. Sorted or better.`,
        checks: [['grt', 'easy', `Do three coats in the rain`, `Sorted.`, `Just About.`]]},
      {at: 'SP-CL-LIBRARY', title: `The Clapton Library outreach panel`, read: `The outreach panel outside Clapton Library. Your mural from yesterday has been sprayed over: black paint, a scrawled "VACANT". Nadia Sayeed comes out of her kiosk. "Two men in black fleeces," she says. "Last night. In a van."`,
        text: `The twist: someone defaced it. Clean and repaint: the contested-site lifecycle.`,
        checks: [['mus', 'medium', `Scrub off the black paint with solvent and a wire brush`, `Clean board.`, `It's stubborn. Paint over it.`],
          ['aim', 'easy', `Photograph the van's tyre tracks in the mud by the panel`, `Clear: the same tread as East Cross vans.`, `Blurred.`]]},
      {at: 'SP-SN-ABNEY', title: `The Abney exterior community panel`, read: `The community panel outside Abney Park on Stoke Newington High Street. A woman with a buggy stops to read it as you finish. She takes a photo of the number. She says nothing. She walks on.`,
        text: `Approved.`,
        checks: [['mov', 'easy', `Climb the low wall to reach the top of the panel`, `Up.`, `You graze your knee.`],
          ['whl', 'medium', `Get to Abney before the park closes and the panel's locked behind the gate`, `In before the gate.`, `Locked out.`]]}
    ],
    closeTitle: `Read aloud: rights`,
    close: `Rosa stands in front of the restored Clapton Library panel, arms folded. "They sprayed VACANT on it," she says. "On a board that says you have rights." She shakes her head. "You know what that tells me?" She turns to you. "It tells me it's working." She pats the panel. "Do it again if they do it again. And again. Notices are cheap. Rights aren't."`,
    notes: [`Sorted or better.`,
      `Board cleanup and repaint shows the contested-site lifecycle.`,
      `East Cross vans defacing the board links to MR.`,
      `Reward: £130 and 1 BM Renown. Leads to TG-BM-03.`]
  },
  'tg-bm-03': {
    brief: `The community project finishes with a three-stop fundraising mural series: the Round Chapel event-load shutter, the De Beauvoir Block authorised mural and the Union Chapel event display wall. One Smashed It or better. Two branches affect BM and MR stance; no damage to civic buildings. The twist: a donor tied to Meridian wants their name larger than the families'.`,
    openTitle: `Read aloud: a borough remembers`,
    open: `Rosa lays out a design: a long mural of faces, drawn from photos of families who've lived in the six buildings, with their names underneath. "A borough remembers," she says. "Three walls. The Round Chapel, De Beauvoir, the Union Chapel." She sighs. "There's a donor who'll pay for the paint. Generous." She taps a name at the bottom: VOSS FOUNDATION. "He wants his name bigger than the families'."`,
    cast: ['rosa-baptiste', 'gwen-price'],
    people: {'celia-voss': {}},
    roles: {'rosa-baptiste': `Wants the families remembered.`, 'gwen-price': `Brought the families' photos.`, 'celia-voss': `Off stage. The Voss Foundation is the donor.`},
    scenes: [
      {at: 'SP-HC-ROUND-SHUTTER', title: `The Round Chapel event-load shutter`, read: `The Round Chapel's shutter, where your Chainring cog once went. Gwen Price hands you a folder of photos: two hundred faces. "Every family," she says. "Every one."`,
        text: `Go for Smashed It: the faces.`,
        checks: [['grt', 'hard', `Paint forty faces from photos, one by one, through the night`, `By dawn, forty faces look back at you. Smashed It.`, `Twenty faces. Sorted.`]]},
      {at: 'SP-DB-DEBEAUVOIR', title: `The De Beauvoir Block authorised mural`, read: `The De Beauvoir Block's mural wall. A man in a suit from the Voss Foundation stands with a stencil: VOSS FOUNDATION, in letters three feet high. "The donor's name goes here," he says, pointing above the families. "As agreed."`,
        text: `The twist: the donor wants their name larger than the families'. Two branches.`,
        checks: [['btl', 'medium', `Tell the Foundation's man the families' names go on top`, `He rings someone. "Fine. Small."`, `He insists. You give in.`],
          ['frt', 'medium', `Negotiate: the donor's name, small, at the bottom, with "thanks to"`, `Agreed.`, `He walks off with the paint money.`]]},
      {at: 'SP-CG-UNION', title: `The Union Chapel event display wall`, read: `The Union Chapel's display wall. A fundraiser is on inside: a choir singing. People come out at the interval and stop to watch you paint.`,
        text: `The final wall. Collections at the interval.`,
        checks: [['mus', 'easy', `Set up the scaffold before the interval crowd comes out`, `Up and safe.`, `It wobbles as the crowd arrives.`],
          ['sav', 'easy', `Notice the families who've come to see their own faces`, `An old man finds his late wife on the wall and cries. You stop and let him.`, `You don't see him.`]]}
    ],
    closeTitle: `Read aloud: remembered`,
    close: `At the Union Chapel fundraiser, a hundred people stand on Compton Terrace in the dark looking at the wall: faces, names, and at the bottom, small or large, the donor's name. An old man stands in front of one face, a woman with grey curls and a big smile. He touches the wall. "Joan," he says. Rosa stands beside him and holds his hand. Nobody says anything. Nobody needs to.`,
    notes: [`One Smashed It or better.`,
      `Two branches affect BM/MR stance. No damage to civic buildings.`,
      `The donor's name size is the moral choice.`,
      `Reward: £220. Completes the BM tagging line.`]
  },
  'tg-ld-01': {
    brief: `Vale uses two consented private markers as part of a covert evidence trail: the Lantern Case Flat rear display panel and the Split Second Archive street shutter. Not sanctioned police graffiti; no badges or impersonation. The twist: a witness is using the markings to work out which detective they can trust.`,
    openTitle: `Read aloud: the lantern code`,
    open: `DS Vale slides a sketch across the table at the Lantern Case Flat: a small lantern with a keyhole in it. "Not police," she says. "Not a badge. Just a sign." She taps it. "A witness I can't name needs to know which doors are safe. If they see this, they can knock." She looks at you. "Two places. Mine, and the Archive. Both owners have said yes."`,
    cast: ['harriet-vale', 'ada-march'],
    people: {'isla-dunn': {}},
    roles: {'harriet-vale': `Setting up a covert trail for a witness.`, 'ada-march': `"Index." Owns the Archive shutter. Said yes.`, 'isla-dunn': `The witness, possibly. Watching to see which detective is safe.`},
    scenes: [
      {at: 'SP-BG-LANTERN', title: `The Lantern Case Flat rear display panel`, read: `The rear stair at the Lantern Case Flat, a small display panel by the bins. Vale watches from the kitchen window with a coffee. Milk, no sugar.`,
        text: `Consented private marker.`,
        checks: [['grf', 'medium', `Paint the keyhole so small and precise it only reads up close`, `Perfect: from three metres, it's just a lantern.`, `Too obvious.`]]},
      {at: 'SP-DB-ARCHIVE', title: `The Split Second Archive street shutter`, read: `Index's street shutter. She stands on the step with an index card: "LANTERN — LD — SAFE." As you paint, a young woman in a response officer's fleece walks past slowly, looks at the lantern, and looks at you. Then she walks on.`,
        text: `The twist: a witness is using the markings to decide which detective to trust.`,
        checks: [['sav', 'medium', `Recognise the passer-by`, `PC Isla Dunn. She's checking whether Vale is safe to trust.`, `Just a passer-by.`],
          ['btl', 'easy', `Keep painting calmly while she watches`, `She sees you're steady. She nods.`, `You look away. She hurries on.`]]}
    ],
    closeTitle: `Read aloud: a safe door`,
    close: `Two nights later, Vale finds a note pushed under the Lantern Case Flat door, folded small. One line, in blue biro, with a sticky tab on it: "I saw the lantern. I'll talk. — I.D." Vale reads it twice, then puts it in her pocket. "The lantern worked," she says. She looks at you. "You don't need to know who." She smiles slightly. "But thank you."`,
    notes: [`Not sanctioned police graffiti. No badges or impersonation.`,
      `The witness is Isla Dunn (LD2). She uses the mark to decide to trust Vale.`,
      `Reward: £65. Leads to TG-LD-02.`]
  },
  'tg-ld-02': {
    brief: `Three discreet symbols reveal how false reports were being routed: the Well Street service underpass, the Chainring Storehouse boundary wall and the Shacklewell Arms loading shutter. Sorted or better. When a public mark is unauthorised, Heat applies like any other faction. The twist: the Chainring can read the third sign differently.`,
    openTitle: `Read aloud: between the lines`,
    open: `Vale lays three photos on the case board: an underpass, a wall, a shutter. "False reports were routed through these three places," she says. "Couriers picked up envelopes. Marked them with a sign so the next courier knew." She points at a small chalk triangle in each photo. "Paint over the triangle with the lantern. So the next courier knows we know." She pauses. "The Storehouse wall is Pat's."`,
    cast: ['harriet-vale', 'auntie-pat', 'mags-cole'],
    roles: {'harriet-vale': `Marking the false-report route.`, 'auntie-pat': `The Storehouse wall is hers. She reads signs differently.`, 'mags-cole': `At the Shacklewell. Saw the couriers.`},
    scenes: [
      {at: 'SP-WS-WELLSTREET', title: `The Well Street service underpass`, read: `The service underpass off Well Street: dark, damp, a chalk triangle on the wall at knee height. A light flickers.`,
        text: `Unauthorised public mark: Heat applies.`,
        checks: [['mov', 'medium', `Get in and out of the underpass without being seen from either end`, `Unseen.`, `A cyclist sees you.`]]},
      {at: 'SP-HC-STOREHOUSE', title: `The Chainring Storehouse boundary wall`, read: `The Storehouse wall, with your Chainring cog on it. Beside it, a chalk triangle. Pat comes out of the roller door with her tea. She looks at the triangle, then at the lantern you're about to paint. "Darling," she says. "In my world, a lantern means 'police watching'." She sips. "Are they?"`,
        text: `The twist: the Chainring reads the sign differently.`,
        checks: [['frt', 'medium', `Explain to Pat what the lantern means here, without giving away Vale`, `"Ah. Then it means what it means." She nods. "Paint it."`, `She's suspicious. "Whose sign is it?"`],
          ['grt', 'easy', `Have a cup of tea with Pat first, because you can't refuse`, `Two cups. She tells you who's been leaving the triangles: a courier in a black fleece.`, `You decline. She's offended.`]]},
      {at: 'SP-SN-SHACKLEWELL', title: `The Shacklewell Arms loading shutter`, read: `The Shacklewell's loading shutter. A chalk triangle. Mags Cole in the bay with her gaffer-tape bracelet. "Couriers in black fleeces," she says. "Every Tuesday. Envelopes." She shrugs. "Not my business."`,
        text: `Sorted or better.`,
        checks: [['whl', 'medium', `Get round all three sites before the next Tuesday pick-up`, `Done by Monday night.`, `Tuesday. They've been.`],
          ['mus', 'easy', `Lift the heavy shutter halfway so you can paint the inner face, out of sight`, `Up.`, `It slams back down.`]]}
    ],
    closeTitle: `Read aloud: we know`,
    close: `On Tuesday, Vale watches from a parked car on Shacklewell Lane. A courier in a black fleece walks up to the loading shutter, sees the lantern where his triangle was, and stops dead. He looks around. Then he turns and walks away very fast, without leaving his envelope. Vale writes the time in her notebook. "Between the lines," she says. "Now they know we know."`,
    notes: [`Sorted or better. Unauthorised public marks carry Heat like any other.`,
      `The Chainring reads a lantern as "police watching". Pat's reaction is a fun beat.`,
      `Reward: £130 and 1 LD Renown. Leads to TG-LD-03.`]
  },
  'tg-ld-03': {
    brief: `An evidence-marking operation spans bridge and transit imagery before statements are taken: the Carpenters Road bridge pier, the Orient Way yard carriage and the Pudding Mill Lane stationary DLR carriage. A stationary prop and evidence route; it doesn't present official policing as gang territory. One Smashed It. The twist: a former officer planted a decoy symbol on one carriage.`,
    openTitle: `Read aloud: a light in the wrong place`,
    open: `Vale lays three photos on the case board: the Carpenters Road pier, two train carriages. "Before we take statements, I want the route marked," she says. "So when the witnesses tell their story, we can stand where it happened." She points at the second carriage. "Someone's already put a lantern there." She looks at you. "Not you. Not me."`,
    cast: ['harriet-vale'],
    people: {'gavin-holt': {}},
    roles: {'harriet-vale': `Marking the evidence route.`, 'gavin-holt': `A former officer of his planted a decoy.`},
    scenes: [
      {at: 'SP-ST-CARPENTERS', title: `The Carpenters Road bridge pier`, read: `The Carpenters Road pier, under the orange lamp, for the last time. The fox sits and watches.`,
        text: `Stationary evidence route.`,
        checks: [['grt', 'easy', `Paint carefully in the cold, knowing a witness will stand here`, `Sorted.`, `Just About.`]]},
      {at: 'SP-HM-ORIENT-TRAIN', title: `The Orient Way yard carriage`, read: `The Orient Way yard carriage. On the end, a lantern: but the keyhole is upside down. A decoy. Someone who knew Vale's mark, and got it slightly wrong.`,
        text: `The twist: a former officer planted a decoy.`,
        checks: [['sav', 'medium', `Spot the decoy's mistake`, `The keyhole's upside down. Someone copied it from a description, not the real thing.`, `It looks right to you.`],
          ['grf', 'medium', `Strip the decoy with solvent before painting the real one`, `Clean.`, `It smears.`]]},
      {at: 'SP-BF-DLR', title: `The Pudding Mill Lane stationary DLR carriage`, read: `The DLR carriage at Pudding Mill Lane, out of service. Wind across the concrete. Go for Smashed It: this is where the witness got off the train.`,
        text: `Stationary prop only.`,
        checks: [['aim', 'medium', `Get the keyhole perfectly centred on the carriage door`, `Smashed It.`, `Off-centre. Sorted.`],
          ['whl', 'medium', `Get away before the next DLR rolls past on the main line`, `Gone.`, `The driver sees you.`]]}
    ],
    closeTitle: `Read aloud: upside down`,
    close: `Vale photographs the decoy before you strip it: the upside-down keyhole. "Someone who's heard about the lantern," she says, "but never seen it." She puts the photo on the case board next to a photo of Gavin Holt. "His old sergeant," she says. "Retired last year. Still does favours." She steps back. "A light in the wrong place." She takes a long breath. "Now we take the statements."`,
    notes: [`A stationary prop and evidence route. Don't present official policing as gang territory.`,
      `One Smashed It or better.`,
      `The decoy points at Holt's network (LD career).`,
      `Reward: £220. Completes the LD tagging line.`]
  },
  'tg-mr-01': {
    brief: `Rusk sponsors corporate-style arrows on two privately controlled display surfaces: the Orchard Lease Office shutter and the Stratford loading-bay wall. Corporate ads, with a competing permitted community option. The twist: residents contest whether consent was really obtained.`,
    openTitle: `Read aloud: Meridian says welcome`,
    open: `Rusk hands you a stencil: a silver arrow curving into a circle, and the word WELCOME. "Two surfaces," he says. "Privately controlled. Permission obtained." One second's pause. "Orchard Lease Office. Westfield loading bay." He holds your eye. "Paint them. Professionally." He leaves the stencil on the table and walks away.`,
    cast: ['martin-rusk', 'mina-dey'],
    people: {'kit-dey': {}},
    roles: {'martin-rusk': `Sponsors the corporate arrows.`, 'mina-dey': `At the Orchard Lease Office. Wasn't asked about permission.`, 'kit-dey': `Offers a competing community design.`},
    scenes: [
      {at: 'SP-HB-ORCHARD', title: `The Orchard Lease Office shutter`, read: `The Orchard Lease Office shutter. Mina Dey comes out as you set up, flustered. "Nobody asked me," she says. "Nobody asked anybody. The residents upstairs didn't agree to this."`,
        text: `The twist: residents contest whether consent was obtained.`,
        checks: [['frt', 'medium', `Ask the residents upstairs whether they agree`, `They don't. They offer you their own design instead.`, `They slam the door.`]]},
      {at: 'SP-ST-WESTFIELD', title: `The Stratford loading-bay wall`, read: `The Westfield loading bay. Kit Dey, the print worker, is waiting with a roll of paper. "Community design," she says. "Same wall. Same permission. Our lot." She unrolls it: hands, homes, the word STAYING. "Your choice."`,
        text: `A competing permitted community option.`,
        checks: [['btl', 'medium', `Choose, and tell Rusk's man which you painted`, `Whatever you chose, you said it plainly.`, `You don't tell him. He finds out.`],
          ['mus', 'easy', `Move the roll cages blocking the wall`, `Moved.`, `One rolls into a lorry.`]]}
    ],
    closeTitle: `Read aloud: welcome`,
    close: `Rusk walks past the Westfield loading bay the next day and stops. Whatever is on the wall (WELCOME, or STAYING), he looks at it for exactly three seconds. Then he takes out his phone, photographs it, and walks on. He doesn't ring you. He doesn't need to.`,
    notes: [`Corporate ads, with a competing permitted community option.`,
      `Residents contest consent: the choice affects MR and BM stance.`,
      `Reward: £65. Leads to TG-MR-02.`]
  },
  'tg-mr-02': {
    brief: `Celia Voss uses a symbol campaign to suggest a new area boundary: the Glasshouse Saleroom service shutter, the Well Street service underpass and the Roman Rooms Printworks commissioned board. Sorted or better. Public opposition triggers rival-tag opportunities. The twist: a planning diagram is falsified, and a misaligned stencil reveals it.`,
    openTitle: `Read aloud: new boundary, new banner`,
    open: `Celia shows you a map on her tablet: a new area, drawn in silver, with a name: "EAST BANK QUARTER". "Three markers," she says. "So people start to think of it as one place." She smiles. "The Glasshouse, Well Street, the Printworks." She hands you a stencil: a silver line with a dot at each end. "Line them up with the map, darling. Precisely."`,
    cast: ['celia-voss', 'clement-wren', 'kit-dey'],
    roles: {'celia-voss': `Drawing a new boundary with paint.`, 'clement-wren': `Lets you use the Glasshouse shutter. Amused.`, 'kit-dey': `At the Printworks. Notices the stencil doesn't match the planning diagram.`},
    scenes: [
      {at: 'SP-CG-GLASSHOUSE', title: `The Glasshouse Saleroom service shutter`, read: `The Glasshouse shutter. Clement watches from his window. "East Bank Quarter," he says, when you show him the map. "How very estate agent."`,
        text: `Sorted or better.`,
        checks: [['grt', 'easy', `Get the silver paint even on the ridged shutter`, `Sorted.`, `Streaky.`]]},
      {at: 'SP-WS-WELLSTREET', title: `The Well Street service underpass`, read: `The Well Street underpass. Your lantern from Vale's job is still here. A group of residents is waiting. "Not here," one says. "This isn't East Bank anything. This is Well Street."`,
        text: `Public opposition triggers rival-tag opportunities.`,
        checks: [['mov', 'medium', `Leave without a confrontation`, `You step back. They paint WELL STREET over the space instead.`, `It gets heated.`]]},
      {at: 'SP-OF-PRINT', title: `The Roman Rooms Printworks commissioned board`, read: `The Printworks board on Roman Road. Kit Dey holds the stencil up against the planning diagram. "Look," she says. "The stencil's dots are two metres further east than the diagram. The 'boundary' includes three buildings the diagram doesn't." She looks at you. "Someone's moved the line."`,
        text: `The twist: a misaligned stencil reveals a falsified planning diagram.`,
        checks: [['sav', 'medium', `Compare the stencil to the diagram and find the three extra buildings`, `The Arches, Essex Dry Goods, the Clapton Union Rooms.`, `They look aligned.`],
          ['aim', 'medium', `Photograph the stencil laid over the diagram, perfectly square`, `Clear proof.`, `Skewed. Arguable.`]]}
    ],
    closeTitle: `Read aloud: the line moved`,
    close: `Kit Dey pins the photo on the Printworks noticeboard: the stencil, the diagram, three buildings that shouldn't be inside the line. "They moved the boundary," she says. "With paint." She laughs. "Paint. Our paint." She takes a can from the shelf and hands it to you. "Well. Paint works both ways."`,
    notes: [`Sorted or better.`,
      `Public opposition triggers rival-tag opportunities.`,
      `The misaligned stencil exposes a falsified planning diagram (E1).`,
      `Reward: £130 and 1 MR Renown. Leads to TG-MR-03.`]
  },
  'tg-mr-03': {
    brief: `Mark a chain of development-adjacent sites as Meridian's city push: the VeloPark approach footbridge panel, the East Cross overpass pillar and the Bow Flyover column. Both routes count for story progress but give different faction standings. One Smashed It. The twist: a community organiser offers to turn it into a protest mural.`,
    openTitle: `Read aloud: the golden route`,
    open: `Rusk hands you a gold stencil: a road with an arrow, and the words THE GOLDEN ROUTE. "VeloPark. East Cross. Bow Flyover." One second's pause. "Meridian's push into the city." He looks at you. "Gold paint. Expensive. Don't waste it."`,
    cast: ['martin-rusk', 'eileen-grant'],
    roles: {'martin-rusk': `Wants the golden route painted.`, 'eileen-grant': `Offers to turn it into a protest mural.`},
    scenes: [
      {at: 'SP-ON-VELO', title: `The VeloPark approach footbridge panel`, read: `The VeloPark footbridge panel. Prisms, reeds and lanterns already on it from other jobs. Room for gold.`,
        text: `One route or the other.`,
        checks: [['grt', 'easy', `Lay down gold leaf paint in the wind, carefully`, `Gleaming.`, `Patchy.`]]},
      {at: 'SP-WW-EASTCROSS', title: `The East Cross overpass pillar`, read: `The East Cross pillar. Eileen Grant is waiting with a clipboard and forty residents. "Paint his gold route if you like," she says. "Or paint ours." She holds up a design: the same road, but with people standing in it, arms linked. "Same paint. Different story."`,
        text: `The twist: a community organiser offers a protest mural.`,
        checks: [['btl', 'medium', `Choose between Rusk's gold and Eileen's protest, in front of forty people`, `Whatever you choose, you say it out loud.`, `You dither. The residents boo.`],
          ['mus', 'medium', `Hold the scaffold steady while the residents paint the people`, `Steady. Forty people paint their own faces.`, `It wobbles.`]]},
      {at: 'SP-BF-PILLAR', title: `The Bow Flyover column`, read: `The Bow Flyover column, for the last time: Lea Boys reed, Owen's poster, prisms, your crew mark. And one clean patch at the top.`,
        text: `Go for Smashed It.`,
        checks: [['aim', 'medium', `Paint the top section from a cherry-picker borrowed from a mate`, `Smashed It.`, `Sorted.`],
          ['whl', 'medium', `Get the cherry-picker back to the yard before it's missed`, `Returned. Nobody noticed.`, `It's been reported stolen.`]]}
    ],
    closeTitle: `Read aloud: same paint, different story`,
    close: `Drive along the A12 the next morning and you'll see it: either a golden road arrowing east, or forty painted residents with linked arms. Rusk drives past in a black car without slowing down. Eileen Grant drives past in her Micra and honks. Whichever you chose, it's there now, on the biggest column in East London, for everyone to see. Same paint. Different story.`,
    notes: [`Both routes count for story progress but give different faction standings (MR or BM).`,
      `One Smashed It or better.`,
      `Reward: £220. Completes the MR tagging line.`]
  },
  'tg-rt-01': {
    brief: `Ada "Index" March gives the crew two linked symbols to make missing names visible: the Split Second Archive street shutter and the Abney exterior community panel. Only authorised panels; symbols still shown as vector art. The twist: the second mark corresponds to a misfiled witness statement.`,
    openTitle: `Read aloud: the red thread begins`,
    open: `Index draws a red line on an index card, a loop at each end. "The Red Thread," she says. "Two marks. One at the Archive, one at Abney." She puts the card down. "When people see them, they'll know someone's looking for the missing. And maybe they'll come and tell us what they know." She looks at you. "Red paint. Only red."`,
    cast: ['ada-march', 'imogen-vale'],
    roles: {'ada-march': `"Index." Making the missing visible.`, 'imogen-vale': `At Abney Books next to the Abney panel. Knows the misfiled statement.`},
    scenes: [
      {at: 'SP-DB-ARCHIVE', title: `The Split Second Archive street shutter`, read: `Index's own shutter. She watches from the step with a cup of tea, pen behind each ear.`,
        text: `Authorised. Red only.`,
        checks: [['aim', 'easy', `Get the loops at each end of the thread perfectly round`, `Perfect circles. Index beams.`, `Wobbly. She's polite.`]]},
      {at: 'SP-SN-ABNEY', title: `The Abney exterior community panel`, read: `The Abney community panel on Stoke Newington High Street. Imogen Vale comes out of Abney Books with a tote bag of records. "A red thread?" she says. "There's a statement in our donations box with a red thread drawn on it. Someone dropped it in last month." She frowns. "I thought it was a bookmark."`,
        text: `The twist: the second mark corresponds to a misfiled witness statement.`,
        checks: [['sav', 'medium', `Recognise the statement's significance when Imogen shows you`, `A witness statement about the night Nia went quiet, misfiled as a donation.`, `A piece of paper with a red line.`],
          ['grt', 'easy', `Dig through the donations box with Imogen`, `Found, under a stack of Jilly Coopers.`, `You give up.`]]}
    ],
    closeTitle: `Read aloud: someone's looking`,
    close: `Index unfolds the misfiled statement on her photograph table. Two pages, handwritten, signed, with a red thread drawn in the corner by someone who'd seen an old flyer. "Someone tried to tell us months ago," she says. "And it ended up in a box of books." She files it under N. Then she writes a new card: "Red thread works." She pins it to the wall.`,
    notes: [`Only authorised panels. Symbols still shown as vector art.`,
      `The misfiled statement links to RT6.`,
      `Reward: £65. Leads to TG-RT-02.`]
  },
  'tg-rt-02': {
    brief: `Three markings identify places where stories disagree: the Estorick pop-up board, the Englefield back-lane wall and the Lantern Case Flat rear display panel. Sorted or better. A puzzle-like sequence, with no arbitrary real-time street puzzle. The twist: the middle tag is deliberately inverted; correct it to reveal the trail.`,
    openTitle: `Read aloud: stitches on the map`,
    open: `Index lays three photos in a row. "Three places where people's stories don't match," she says. "An art preview, Leon's back lane, Vale's flat." She draws a red thread through all three on a map, with a stitch at each. "Paint a stitch at each one. Then stand back and look." She smiles. "The pattern tells you something."`,
    cast: ['ada-march', 'leon-marsh', 'harriet-vale'],
    roles: {'ada-march': `"Index." Mapping disagreements.`, 'leon-marsh': `Lets you paint his back lane wall.`, 'harriet-vale': `Lets you use her rear panel.`},
    scenes: [
      {at: 'SP-CG-ESTORICK', title: `The Estorick pop-up board`, read: `The Estorick pop-up board. A prism, your work from Clement's job, already on it. Room for a stitch.`,
        text: `Sorted or better.`,
        checks: [['grt', 'easy', `Paint the stitch carefully, matching Index's diagram`, `Sorted.`, `Just About.`]]},
      {at: 'SP-LF-LISTENING', title: `The Englefield back-lane wall`, read: `The back lane behind Leon's flat on Englefield Road. Leon leans out of his window. "There's already a red stitch there," he says. "Upside down. Somebody painted it last week." He frowns. "Not you?"`,
        text: `The twist: the middle tag is deliberately inverted. Correct it to reveal the trail.`,
        checks: [['sav', 'medium', `Work out why someone inverted it`, `Inverted, the stitch points away from Leon's. Corrected, it points at his record cupboard.`, `You don't see it.`],
          ['grf', 'medium', `Strip the inverted stitch cleanly before repainting`, `Clean.`, `It smears.`]]},
      {at: 'SP-BG-LANTERN', title: `The Lantern Case Flat rear display panel`, read: `Vale's rear panel. Your lantern's still here. Vale comes down the stairs. "A stitch next to my lantern?" she says. "Fine. As long as it doesn't point at my kitchen."`,
        text: `Sorted or better.`,
        checks: [['mov', 'easy', `Get down the rear stair with the paint without banging on Vale's door`, `Silent.`, `You knock a bin over. Vale sighs.`],
          ['whl', 'medium', `Do all three sites in one night before the trail goes cold`, `Done by dawn.`, `Two nights.`]]}
    ],
    closeTitle: `Read aloud: the pattern`,
    close: `Index stands back from her map with three red stitches on it, the middle one now the right way up. She draws a line through them. It points straight at Leon's flat. "Leon's record cupboard," she says. She rings him. "Leon. What have you got in that cupboard that someone didn't want us to find?" A long pause on the line. Then Leon says, very quietly, "Ah."`,
    notes: [`Sorted or better. A puzzle-like sequence, no real-time street puzzle.`,
      `The inverted stitch points at Leon's record cupboard. What's in it is the GM's call (an old Nia session, a letter).`,
      `Reward: £130 and 1 RT Renown. Leads to TG-RT-03.`]
  },
  'tg-rt-03': {
    brief: `Leave three linked clues between transport, towpath and flyover: the Temple Mills depot carriage, the Tern Wharf canal parapet and the Bow Flyover column. Use the revision history to identify overpainting, then repair the correct spot. One Smashed It. The twist: one previously painted symbol has been overpainted by Meridian.`,
    openTitle: `Read aloud: the thread cannot break`,
    open: `Index has a new map pinned to the wall: red threads everywhere. "Three more," she says. "Temple Mills, Tern Wharf, the flyover." She taps the flyover. "Someone painted over one of ours there. Silver paint." She looks at you. "Check the Tagbook's revision history. Find which one. Repair it." She folds her arms. "The thread cannot break."`,
    cast: ['ada-march', 'mara-boyd'],
    roles: {'ada-march': `"Index." Repairing the thread.`, 'mara-boyd': `Tern. Lets you use the Tern Wharf parapet.`},
    scenes: [
      {at: 'SP-HM-TEMPLE-TRAIN', title: `The Temple Mills depot carriage`, read: `The Temple Mills carriage. Your old marks, other crews' marks, a whole history in paint.`,
        text: `Trains add three minutes on the Watch.`,
        checks: [['sav', 'easy', `Spot the patrol's torch in time`, `Clear.`, `Spotted.`]]},
      {at: 'SP-HX-TERN', title: `The Tern Wharf canal parapet`, read: `The Tern Wharf parapet: Tern's bird, Moth's reed, your marks. Tern waves from the dispatch room window.`,
        text: `Sorted or better.`,
        checks: [['mov', 'medium', `Lean out over the canal to paint the parapet's outer face`, `Steady.`, `Wet shoe.`]]},
      {at: 'SP-BF-PILLAR', title: `The Bow Flyover column`, read: `The Bow Flyover column. The Tagbook's revision history shows it: the red thread you painted for Index (or someone did) was covered last week with silver. Meridian's silver. The golden route, or the East Bank line.`,
        text: `The twist: Meridian overpainted a symbol. Use the revision history to find it, then repair it. Go for Smashed It.`,
        checks: [['grf', 'medium', `Strip the silver back to the red underneath with solvent`, `The red thread shows through.`, `It all comes off together.`],
          ['aim', 'medium', `Repaint the thread at the top of the column from a borrowed cherry-picker`, `Smashed It.`, `Sorted.`],
          ['btl', 'medium', `Keep working when a Meridian van pulls up and the driver gets out to watch`, `He watches. He gets back in. He drives off.`, `You stop. He photographs you.`]]}
    ],
    closeTitle: `Read aloud: the thread`,
    close: `Index walks the whole route the next day with a camera: Temple Mills, Tern Wharf, the flyover. At the flyover, she stands for a long time looking up at the red thread, restored, over the silver. "They painted over it," she says. "And you painted it back." She takes a photo. "That's the whole job, really." She writes a card and pins it to her wall: "The thread cannot break."`,
    notes: [`Use the Tagbook's revision history to find the overpaint.`,
      `One Smashed It or better.`,
      `Reward: £220. Completes the RT tagging line.`]
  },
  'tg-city-01': {
    brief: `Put the crew's mark into five distinct districts and include at least two unlocked sponsor identities; the Tagbook records the spread: the Oddments Lockup yard wall, the Backspin Studio loading shutter, the Grow Hackney canal retaining wall, the Carpenters Road bridge pier and the Bow Flyover column. Each Just About or better; at least two Smashed It. The twist: one sponsoring faction objects to appearing beside another. Resolve it instead of auto-claiming their Renown.`,
    openTitle: `Read aloud: from Lea to Bow`,
    open: `Kez spreads every map he owns across the floor of the flat. "Five districts," he says. "Highbury, Dalston, the Wick, Stratford, Bow." He draws a line through them. "Your mark, and at least two of your sponsors'. Chainring and Dead Air. Or Lea Boys and the Market. Whatever you've earned." He sits back. "From Lea to Bow. Everyone sees it." He grins. "Then you're not a crew. You're a city."`,
    cast: ['kez', 'auntie-pat', 'jules-akin'],
    roles: {kez: `Planned the whole thing.`, 'auntie-pat': `A sponsor, if the crew have the Chainring pack.`, 'jules-akin': `Patch. A sponsor, if they have the Dead Air pack.`},
    scenes: [
      {at: 'SP-HB-ODDMENTS', title: `The Oddments Lockup yard wall`, read: `The Oddments yard wall: the Chainring cog from TG-CH-02. Room beside it.`,
        text: `Mark one of five.`,
        checks: [['grt', 'easy', `Start at dawn and keep going all day`, `Steady pace.`, `Slow start.`]]},
      {at: 'SP-DA-BACKSPIN', title: `The Backspin Studio loading shutter`, read: `Backspin's shutter: the Dead Air wave. Patch leans out of the rear stair door. "Our wave next to Pat's cog?" he says. "Pat'll go mad. She thinks we're too loud."`,
        text: `The twist: one sponsor objects to appearing beside another.`,
        checks: [['frt', 'medium', `Resolve the dispute between Patch and Pat on speakerphone`, `"Fine. Separate walls." They agree.`, `They argue for twenty minutes.`]]},
      {at: 'SP-VW-WICK-CANAL', title: `The Grow Hackney canal retaining wall`, read: `The Grow Hackney canal wall. Eileen's protest mural, Moth's reed. Room for yours.`,
        text: `Mark three of five.`,
        checks: [['mov', 'medium', `Paint from a narrowboat's roof again`, `Steady.`, `Wobble.`]]},
      {at: 'SP-ST-CARPENTERS', title: `The Carpenters Road bridge pier`, read: `The Carpenters Road pier. The fox watches, as ever.`,
        text: `Go for Smashed It.`,
        checks: [['aim', 'medium', `Your best ever lettering`, `Smashed It.`, `Sorted.`]]},
      {at: 'SP-BF-PILLAR', title: `The Bow Flyover column`, read: `The Bow Flyover column. Every faction's mark is here now. The top patch is the last clean space in East London.`,
        text: `The last of five. Go for Smashed It.`,
        checks: [['mus', 'medium', `Set up the borrowed scaffold tower in the middle of the night`, `Up and safe.`, `It takes an hour.`],
          ['whl', 'medium', `Get through five districts in one day`, `Done by midnight.`, `Two days.`]]}
    ],
    closeTitle: `Read aloud: a city`,
    close: `Kez stands on the roof of a car park in Stratford at sunrise with binoculars, slowly turning. "Highbury," he says. "Dalston. The Wick. Carpenters Road." He turns to the flyover. "Bow." He lowers the binoculars. "Every one." He looks at you, and for once he doesn't grin. He just nods. "You're not a crew any more," he says. "You're a city."`,
    notes: [`Five specific sites plus at least two distinct sponsor packs. Sponsor identity can vary by site.`,
      `All records must be distinct site IDs, unique to this mission run.`,
      `One sponsor objects to appearing beside another: resolve it rather than auto-claiming their Renown.`,
      `Reward: £300. Leads to TG-CITY-02.`]
  },
  'tg-city-02': {
    brief: `Reclaim five contested sites across five districts after their earliest tags have been overwritten or cleaned, and show that the city responds: the Lea Bridge Social Rooms side wall, the Split Second Archive street shutter, the Temple Mills depot carriage, the Tern Wharf canal parapet and the Bethnal Green market service shutter. Proof needs legal surface history (revisions), not just retagging a clean site. At least one Smashed It. The twist: a rival group proposes a joint community wall, giving a lasting peace ending.`,
    openTitle: `Read aloud: nothing stays painted`,
    open: `Kez comes in with a face like a funeral. "They've been cleaned," he says. "Half of them. Council, Meridian, rival crews." He scrolls through photos: grey walls where your marks used to be. "Nothing stays painted." Then he looks up, and the grin comes back. "So we paint it again. Every one. Five districts." He holds up a can. "That's the job. That's always been the job."`,
    cast: ['kez', 'tessa-price', 'pearl-okonkwo', 'mara-boyd', 'ada-march'],
    roles: {kez: `Won't let the city forget.`, 'tessa-price': `Moth. The Social Rooms wall.`, 'pearl-okonkwo': `The Bethnal Green shutter.`, 'mara-boyd': `Tern. The Tern Wharf parapet.`, 'ada-march': `"Index." The Archive shutter.`},
    scenes: [
      {at: 'SP-CL-LEABRIDGE', title: `The Lea Bridge Social Rooms side wall`, read: `The Social Rooms wall, cleaned grey. Moth sits on her bench. "Council did it," she says. "All of ours too." She stands up. "Want help?"`,
        text: `Proof requires surface history: the Tagbook shows the revision.`,
        checks: [['frt', 'easy', `Accept Moth's help and paint together`, `Two crews, one wall.`, `You say no. She shrugs.`]]},
      {at: 'SP-DB-ARCHIVE', title: `The Split Second Archive street shutter`, read: `Index's shutter, cleaned. She's furious. "Somebody power-washed it," she says. "With my red thread on it." She hands you a can of red.`,
        text: `Reclaim it.`,
        checks: [['grt', 'easy', `Repaint everything that was there, from the Tagbook's history`, `Every mark back.`, `Some marks forgotten.`]]},
      {at: 'SP-HM-TEMPLE-TRAIN', title: `The Temple Mills depot carriage`, read: `The Temple Mills carriage, scrubbed clean, gleaming. Not one mark left.`,
        text: `Go for Smashed It.`,
        checks: [['aim', 'medium', `Your best ever piece on the cleanest canvas you've ever had`, `Smashed It. Possibly Legendary.`, `Sorted.`],
          ['sav', 'easy', `Spot the patrol in time`, `Clear.`, `Spotted.`]]},
      {at: 'SP-HX-TERN', title: `The Tern Wharf canal parapet`, read: `The Tern Wharf parapet, cleaned. Tern stands on it. "Moth's been on the radio," she says. "She wants a joint wall. All of us. Lea Boys, Towpath, Market, the lot." She looks at you. "One wall. Everyone's mark. Nobody paints over anybody." She shrugs. "Peace, I suppose."`,
        text: `The twist: a rival group proposes a joint community wall: a lasting peace ending.`,
        checks: [['btl', 'medium', `Back the joint wall, out loud, on Tern's radio, to everyone`, `The radio fills with "Copy. Copy. Copy." Everyone's in.`, `You hedge. Someone backs out.`],
          ['mov', 'medium', `Lean out over the canal for the parapet's face`, `Steady.`, `Splash.`]]},
      {at: 'SP-BG-STREET', title: `The Bethnal Green market service shutter`, read: `The Bethnal Green market shutter, cleaned. Pearl is waiting with a tea urn and every faction's painter: Moth's lot, Tern's drivers, Patch with a stencil, Index with red paint, Pat with eight teeth on a Post-it. "One wall," Pearl says. "Everybody eats."`,
        text: `The joint wall, if the crew backed it. The final reclaimed site.`,
        checks: [['mus', 'medium', `Set up the scaffold for twenty painters at once`, `Up and safe. Everyone climbs on.`, `It takes all morning.`],
          ['whl', 'medium', `Get round all five districts in one day`, `Done by dusk.`, `Two days.`]]}
    ],
    closeTitle: `Read aloud: nothing stays painted`,
    close: `At dusk, the Bethnal Green market shutter is covered from edge to edge: a Chainring cog with eight teeth, a Dead Air wave with three lines, a Lea Boys reed, a Night Market lantern with four lines of light, a tern in flight, a red thread, and, in the middle, your crew's mark. Twenty painters stand back and look at it. Nobody's painted over anybody. Kez takes a photo. "Nothing stays painted," he says. "So we keep painting." He grins. "That's the job."`,
    notes: [`Proof requires legal surface history (Tagbook revisions), not just retagging a clean site.`,
      `All records must be distinct site IDs, unique to this mission run.`,
      `A joint community wall gives a lasting peace ending between the tagging factions.`,
      `Reward: £500. The finale of Street Commissions.`]
  }
};
